data.solution:
l = [i.split(":")for i in input().split()]
h = dict(l)
s = input()
p = ""

start = s.find("AUG")
if start > 0:
    s = s[start:]
    try:
        for i in range(0, len(s), 3):
            if h[s[i:i+3]] != "STOP":
                p += h[s[i:i+3]] + " "
            else:
                p += "STOP"
                break
    except:
        p="ELIMINATE"

print(p if p else "NONE")
